/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `chat_messages` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) DEFAULT NULL,
  `message` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_at` bigint(20) NOT NULL,
  `is_deleted` tinyint(4) DEFAULT 0,
  `guest_fp` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `guest_ip` varchar(45) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_guest` tinyint(4) DEFAULT 0,
  `is_bot` tinyint(4) DEFAULT 0,
  `bot_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_chat_created` (`created_at`),
  KEY `idx_chat_user` (`user_id`),
  KEY `idx_chat_guest_fp` (`guest_fp`)
) ENGINE=InnoDB AUTO_INCREMENT=309 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
